CREATE TABLE IF NOT EXISTS tenants(id text primary key,subscription_id text unique not null,business_name text not null,owner_email text not null,plan_slug text not null,plan_limits jsonb not null default '{}',status text not null check(status in('ACTIVE','SUSPENDED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS provisioning_events(event_id text primary key,tenant_id text not null references tenants(id),created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS product_sessions(token_hash text primary key,tenant_id text not null references tenants(id),user_id text not null,email text not null,expires_at timestamptz not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS products(id bigserial primary key,tenant_id text not null references tenants(id),name text not null,sku text not null,price_minor integer not null check(price_minor>=0),currency text not null default 'USD',stock integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,sku));
CREATE TABLE IF NOT EXISTS orders(id bigserial primary key,tenant_id text not null references tenants(id),customer_email text not null,total_minor integer not null check(total_minor>=0),currency text not null,status text not null default 'CONFIRMED',shipping_address jsonb not null default '{}',items jsonb not null default '[]',created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS orders_tenant_created_idx ON orders(tenant_id,created_at desc);
